-- 3.15.1 Israel Reference Catalog v1, comparable-source batch 1.
-- Retrieved 2026-09-28. Every row is an additional offer for an existing exact
-- identity. Similar but dimensionally or commercially different products are
-- deliberately excluded. DIY retail is retained as a channel, not a baseline.

on conflict(source_id) do update set source_channel=excluded.source_channel,source_name=excluded.source_name,source_url=excluded.source_url,source_date=excluded.source_date,language_code=excluded.language_code,region=excluded.region,evidence=excluded.evidence,retrieved_at=now();

-- Channel corrections for sources already stored in earlier batches.
update public.reference_sources set source_channel='diy_retail'
where source_id in ('3bcbe9e7-aa91-5d30-9f75-b70d77efa6f5','18dbf61a-1030-5124-b4d6-e76d2f3ba267');
update public.reference_sources set source_channel='trade_supplier'
where source_id in ('1e3425be-a090-5686-87e4-e005a97f4aee','a4f11bd0-2162-5bd1-90fa-2271f3d3d810');
update public.reference_sources set source_channel='specialist_retailer'
where source_id in ('a3fe6a30-0298-5228-b92d-834c887bb844','f3625e84-90e9-5c58-9893-30e077fa61eb','870da1ae-f9e4-5840-862e-8c80d923f9d0','3139c495-ed33-5234-b15b-80af00b928bb');

on conflict(material_id,market_code,language_code,alias_key) do update set alias_kind=excluded.alias_kind,source_id=excluded.source_id,supplier_name=excluded.supplier_name,exact_identity=excluded.exact_identity,confidence=excluded.confidence,active=true,updated_at=now();

on conflict(market_offer_id) do update set source_price=excluded.source_price,source_currency=excluded.source_currency,source_unit=excluded.source_unit,price_scope=excluded.price_scope,included_services=excluded.included_services,delivery_included=excluded.delivery_included,package_quantity=excluded.package_quantity,minimum_order_quantity=excluded.minimum_order_quantity,vat_mode=excluded.vat_mode,normalized_price_ex_vat=excluded.normalized_price_ex_vat,normalized_unit=excluded.normalized_unit,conversion_basis=excluded.conversion_basis,region=excluded.region,valid_from=excluded.valid_from,valid_to=excluded.valid_to,confidence=excluded.confidence,status=excluded.status;
